<script setup>
import {computed} from 'vue';
import CatalogModal from '../catalog/CatalogModal.vue';
import {canReadReceipt,money,saleStatuses,time} from './sales-model.js';
const props=defineProps({vm:Object,sale:Object}),emit=defineEmits(['close','receipt']);
const currency=computed(()=>'د.ع');
</script>
<template><CatalogModal title="تفاصيل العملية" section="سجل المبيعات" content-class="sales-modal" :busy="vm.state.busy" @close="$emit('close')"><div class="sale-detail-banner"><span class="badge" :class="{'warn':sale.status === 'Print Failed'}">{{saleStatuses[sale.status]}}</span><span class="mono">{{sale.id}}</span></div><div v-if="canReadReceipt(sale,vm.identity.value,vm.can) && ['Print Requested','Reprint Requested'].includes(sale.status)" class="notice">البطاقات أُصدرت والمبلغ خُصم. نتيجة الطباعة لم تُسجّل بعد؛ افتح الوصل لمتابعة الطباعة وتسجيل نتيجتها.</div><dl class="account-fields"><div><dt>الوكيل</dt><dd>{{sale.main_account_name || '—'}}</dd></div><div><dt>نقطة البيع / الحساب</dt><dd>{{sale.account_name}}</dd></div><div><dt>الفئة</dt><dd>{{sale.product_name}}</dd></div><div><dt>وقت العملية</dt><dd>{{time(sale.issued_at || sale.created_at)}}</dd></div><div><dt>عدد البطاقات</dt><dd>{{sale.quantity}}</dd></div><div><dt>سعر البطاقة</dt><dd>{{money(sale.price)}} {{currency}}</dd></div><div><dt>المبلغ المخصوم</dt><dd>{{sale.issued_at ? money(sale.credit) : 'لم يصدر الحجز'}} {{sale.issued_at ? currency:''}}</dd></div><div v-if="sale.cost !== undefined && vm.can('data.cost')"><dt>تكلفة البطاقات</dt><dd>{{money(sale.cost)}} {{currency}}</dd></div><div v-if="sale.agent_margin !== undefined && vm.can('data.profit')"><dt>ربح الوكيل على البطاقات الصادرة</dt><dd>{{money(sale.agent_margin)}} {{currency}}</dd></div><div v-if="vm.can('data.profit')"><dt>ربح نقطة البيع</dt><dd>{{money(sale.pos_profit)}} {{currency}}</dd></div><div><dt>عدد طلبات إعادة الطباعة</dt><dd>{{sale.reprints}}</dd></div><div v-if="sale.delivery_reference"><dt>التسليم</dt><dd>{{sale.delivery_channel}} · {{sale.delivery_reference}}</dd></div></dl><h3>سجل الطباعة</h3><div v-if="!sale.attempts?.length" class="empty">لم تُسجّل نتيجة طباعة حتى الآن</div><ol v-else class="sale-print-history"><li v-for="attempt in sale.attempts" :key="attempt.id"><b>{{saleStatuses[attempt.status] || attempt.status}}</b><span>{{time(attempt.finished_at || attempt.started_at)}} · مستخدم #{{attempt.actor_id}} · {{attempt.kind === 'reprint' ? 'إعادة طباعة':attempt.kind === 'retry' ? 'إعادة محاولة':'المحاولة الأولى'}}</span><p v-if="attempt.reason">السبب: {{attempt.reason}}</p></li></ol><div class="formfoot"><button type="button" class="btn" @click="$emit('close')">إغلاق</button><button v-if="canReadReceipt(sale,vm.identity.value,vm.can)" type="button" class="btn primary" @click="$emit('receipt',sale)">{{['Print Requested','Reprint Requested'].includes(sale.status) ? 'متابعة الطباعة':'عرض الوصل'}}</button></div></CatalogModal></template>
